import{_ as l,o as e,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const n=JSON.parse('{"title":"伺服Discord非公開頻道","description":"關於本伺服Discord非公開頻道的說明。","frontmatter":{"title":"伺服Discord非公開頻道","description":"關於本伺服Discord非公開頻道的說明。"},"headers":[],"relativePath":"discord/free_chat/index.md","filePath":"discord/free_chat.md"}'),o={name:"discord/free_chat/index.md"};function t(c,i,d,s,h,u){return e(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="非公開discord頻道-說明" tabindex="-1">非公開Discord頻道 說明 <a class="header-anchor" href="#非公開discord頻道-說明" aria-label="Permalink to &quot;非公開Discord頻道 說明&quot;">​</a></h1><h2 id="說明" tabindex="-1">說明 <a class="header-anchor" href="#說明" aria-label="Permalink to &quot;說明&quot;">​</a></h2><ul><li>當你想聊些<b>不適合在公頻上聊</b>的內容可以來這邊聊 <ul><li>在Discord裡面的任一個頻道輸入<code>/free</code>指令以獲得權限</li></ul></li><li>非公開頻道<b>不適用於</b><a href="/rule/chat/">公開聊天規範</a>，請自行評估是否加入 <ul><li>可能包含<b>令人不適</b>或<b>不適合未成年</b>閱覽的內容</li><li>除另有規定，伺服人員將不介入任何衝突與爭議</li></ul></li><li>當你輸入<code>/free</code>獲取權限後，即視為同意本頻道的相關聲明</li></ul><h2 id="非公開頻道列表" tabindex="-1">非公開頻道列表 <a class="header-anchor" href="#非公開頻道列表" aria-label="Permalink to &quot;非公開頻道列表&quot;">​</a></h2><h3 id="🌌自由的風平" tabindex="-1">🌌自由的風平 <a class="header-anchor" href="#🌌自由的風平" aria-label="Permalink to &quot;🌌自由的風平&quot;">​</a></h3><ul><li>這是個自由的聊天室，可以盡情暢談，不會受到公頻規範的限制 <ul><li>本頻道有同步到遊戲內，訊息發送、接收的管理方式請詳見下方</li></ul></li><li>請<b>自行拿捏尺度</b>，這裡不限制爭吵相關的行為(不受公頻規範管制，伺服方不會介入)。</li><li><b>請不要</b>在這裡發表<b>R18</b>、<b>獵奇</b>的內容，請到『🔞可以色色』發表，也請不要嚴重洗頻 <ul><li>違反本項內容，伺服人員有權力進行處置</li></ul></li></ul><h3 id="🔞可以色色" tabindex="-1">🔞可以色色 <a class="header-anchor" href="#🔞可以色色" aria-label="Permalink to &quot;🔞可以色色&quot;">​</a></h3><ul><li>拿來發表、討論<b>R18</b>、<b>成人內容</b>的地方 <ul><li>本頻道有同步到遊戲內，但僅限接收訊息</li></ul></li><li><font color="red"><b>嚴禁以任何形式發表有關三次元兒童色情、描述血腥、過度暴力的內容</b></font></li><li>若您的內容明顯會<b>令人不適</b>的內容，請註記暴雷並加上警語 <ul><li>若為文字內容，請在開頭加上警語，並將內文前後加上<code>||</code>反黑處理</li><li>違反本項內容，伺服人員有權力進行處置</li></ul></li></ul><h2 id="同步遊戲內聊天室" tabindex="-1">同步遊戲內聊天室 <a class="header-anchor" href="#同步遊戲內聊天室" aria-label="Permalink to &quot;同步遊戲內聊天室&quot;">​</a></h2><ul><li>上述頻道『🌌自由的風平』、『🔞可以色色』，都可以在伺服器內聊天室接收到訊息。</li><li>你可以在遊戲內發送訊息至『🌌自由的風平』。</li></ul><ol><li>請先為您的Discord帳號進行綁定<a href="/discord/">綁定說明</a></li><li>在你要加入的<b>Discord頻道</b>，輸入 <code>/join</code><br><img src="https://i.imgur.com/bEwaFzA.png" alt=""></li><li>加入完成後，會出現此訊息<br><img src="https://i.imgur.com/Po5Fzey.png" style="width:90%;"></li><li>進入伺服內，輸入指令<code>/c</code><br><img src="https://i.imgur.com/o6HZZwa.png" style="width:50%;"><ul><li>點擊第二排的羊毛，可以選擇是否要收到此頻道的訊息。</li><li>點擊第一排的圖示，可以選擇你的聊天室訊息，要發送到哪個頻道。 而第三排的圖示為你目前的發送聊天室要送到哪裡。</li><li>草地是『💻同步頻道』，終界眼是『🌌自由的風平』，牛奶桶是『🔞可以色色』 (『🔞可以色色』不能設定為發送訊息的頻道，只能接收訊息)</li></ul></li></ol><h3 id="常見設定方式-輸入-c設定切換" tabindex="-1">常見設定方式 (輸入<code>/c</code>設定切換) <a class="header-anchor" href="#常見設定方式-輸入-c設定切換" aria-label="Permalink to &quot;常見設定方式 (輸入`/c`設定切換)&quot;">​</a></h3><ul><li>訊息發送至『💻同步頻道』，接收訊息『💻同步頻道』、『🌌自由的風平』、『🔞可以色色』。<br><img src="https://i.imgur.com/o6HZZwa.png" style="width:40%;"></li><li>訊息發送至『🌌自由的風平』，接收訊息『🌌自由的風平』、『🔞可以色色』。<br> (意味著看不到任何『💻同步頻道』的訊息)<br><img src="https://i.imgur.com/60Fzx7R.png" style="width:40%;"></li><li>訊息發送至『💻同步頻道』，接收訊息『💻同步頻道』。<br> (意味著看不到另外兩個頻道的訊息)<br><img src="https://i.imgur.com/Bt6Dw9U.png" style="width:40%;"></li></ul>',13)])])}const m=l(o,[["render",t]]);export{n as __pageData,m as default};
